message.content:
O site precisa funcionar de verdade na internet com salvamento real e contas de usuário separadas. Isso exige um **servidor + banco de dados** (impossível fazer só com um arquivo HTML — navegador não guarda dados de outras pessoas nem protege senhas).

Usei **Node.js + Supabase (banco gratuito na nuvem)** — é "dentro do próprio site" (não usa OAuth, Facebook, Stripe, etc.), roda em hospedagem gratuita, e cada pessoa entra com seu usuário/senha e só vê os próprios gastos.

**Importante:** o banco é um arquivo de configuração com um link (URL + chave). Você pega esse link no Supabase (grátis, 2 min) e cola nele. Depois, suba o projeto num serviço gratuito (Cloudflare Workers — 5 min, eu deixo os passos) e fique no ar.

=== package.json ===
{
  "name": "controle-de-despesas",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "engines": {
    "node": ">=18"
  },
  "scripts": {
    "start": "node src/server.js",
    "dev": "node --watch src/server.js"
  },
  "dependencies": {
    "@supabase/supabase-js": "^2.45.0",
    "bcryptjs": "^2.4.3",
    "cookie": "^0.6.0"
  },
  "devDependencies": {
    "wrangler": "^3.60.0"
  }
}

=== .gitignore ===
node_modules/
.env
.wrangler/
supabase/.temp/

=== wrangler.toml ===
name = "controle-de-despesas"
main = "src/server.js"
compatibility_date = "2024-07-01"
compatibility_flags = ["nodejs_compat"]
usage_model = "bunds"

# Preencha as variáveis de ambiente do Cloudflare (veja README) com:
#   npx wrangler secret put SUPABASE_URL
#   npx wrangler secret put SUPABASE_SERVICE_KEY

=== supabase/schema.sql ===
-- RODE ESTE BLOCO uma única vez na aba SQL Editor do Supabase (veja README).
-- Cria todas as tabelas e regras de segurança.

create table public.users (
  id uuid primary key default gen_random_uuid(),
  username text unique not null,
  email text unique not null,
  password_hash text not null,
  is_admin boolean not null default false,
  is_active boolean not null default true,
  created_at timestamptz not null default now()
);

create table public.categories (
  id uuid primary key default gen_random_uuid(),
  name text unique not null,
  color text not null default '#64748B',
  is_active boolean not null default true,
  created_at timestamptz not null default now()
);

create table public.expenses (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.users(id) on delete cascade,
  category_id uuid not null references public.categories(id) on delete restrict,
  description text not null,
  amount_cents integer not null check (amount_cents >= 0),
  spent_on date not null default current_date,
  created_at timestamptz not null default now()
);

create index expenses_user_spent_idx on public.expenses (user_id, spent_on);
create index expenses_category_idx on public.expenses (category_id);

-- Permite apenas leitura para quem se autenticou; escrita é feita pelo servidor.
alter table public.users enable row level security;
alter table public.categories enable row level security;
alter table public.expenses enable row level security;

create policy "read users" on public.users for select using (auth.role() = 'authenticated');
create policy "read categories" on public.categories for select using (auth.role() = 'authenticated');
create policy "read own expenses" on public.expenses for select using (auth.uid() = user_id);

=== public/index.html ===
<!DOCTYPE html>
<html lang="pt-BR">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Minhas Despesas</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,500;9..144,600;9..144,700&family=Manrope:wght@400;500;600;700;800&display=swap" rel="stylesheet" />
  <link rel="stylesheet" href="/styles.css" />
</head>
<body>
  <!-- ================= LOGIN / CADASTRO ================= -->
  <div id="auth-screen" class="auth-screen hidden">
    <div class="auth-card">
      <div class="auth-brand">
        <span class="brand-dot"></span>
        <div>
          <h1 class="brand-title">Minhas Despesas</h1>
          <p class="brand-sub">Controle do seu dinheiro, simples e seu.</p>
        </div>
      </div>

      <div class="auth-tabs">
        <button id="tab-login" class="auth-tab active" type="button">Entrar</button>
        <button id="tab-register" class="auth-tab" type="button">Criar conta</button>
      </div>

      <form id="auth-form" class="auth-form" autocomplete="on">
        <label class="field">
          <span class="field-label">Usuário</span>
          <input id="auth-username" type="text" autocomplete="username" placeholder="seu nome de usuário" required />
        </label>
        <label class="field" id="email-field">
          <span class="field-label">E-mail</span>
          <input id="auth-email" type="email" autocomplete="email" placeholder="voce@email.com" />
        </label>
        <label class="field">
          <span class="field-label">Senha</span>
          <input id="auth-password" type="password" autocomplete="current-password" placeholder="mínimo 6 caracteres" required />
        </label>

        <button type="submit" id="auth-submit" class="btn btn-primary btn-block">Entrar</button>
        <p id="auth-message" class="auth-message hidden"></p>
      </form>
    </div>
    <p class="auth-footnote">Seus dados ficam só neste site, protegidos por senha.</p>
  </div>

  <!-- ================= APP ================= -->
  <div id="app" class="app hidden">
    <header class="topbar">
      <div class="topbar-left">
        <span class="brand-dot"></span>
        <span class="brand-title-sm">Minhas Despesas</span>
      </div>
      <div class="topbar-right">
        <span id="user-name" class="user-chip"></span>
        <span id="admin-badge" class="admin-badge hidden">Admin</span>
        <button id="logout-btn" class="btn btn-ghost" type="button">Sair</button>
      </div>
    </header>

    <nav class="tabs">
      <button id="tab-me" class="nav-tab active" type="button">Meus gastos</button>
      <button id="tab-admin" class="nav-tab hidden" type="button">Administração</button>
    </nav>

    <main class="content">
      <!-- Meus gastos -->
      <section id="view-me" class="view">
        <div class="page-head">
          <div>
            <h2 class="page-title">Meus gastos</h2>
            <p class="page-sub" id="me-month-label"></p>
          </div>
          <button id="me-refresh" class="btn btn-ghost" type="button">↻ Atualizar</button>
        </div>

        <div class="stats-grid">
          <div class="stat-card stat-hero">
            <p class="stat-label">Gasto no mês</p>
            <p class="stat-value" id="stat-month">R$ 0,00</p>
            <p class="stat-hint" id="stat-month-hint"></p>
          </div>
          <div class="stat-card">
            <p class="stat-label">Total geral</p>
            <p class="stat-value stat-value-sm" id="stat-total">R$ 0,00</p>
            <p class="stat-hint" id="stat-total-hint"></p>
          </div>
          <div class="stat-card">
            <p class="stat-label">Lançamentos</p>
            <p class="stat-value stat-value-sm" id="stat-count">0</p>
            <p class="stat-hint">registrados até hoje</p>
          </div>
        </div>

        <div class="panel">
          <div class="panel-head">
            <h3 class="panel-title">Adicionar gasto</h3>
          </div>
          <form id="expense-form" class="expense-form">
            <div class="form-grid">
              <label class="field">
                <span class="field-label">Descrição</span>
                <input id="exp-desc" type="text" placeholder="Ex.: mercado, uber, cinema" required />
              </label>
              <label class="field">
                <span class="field-label">Valor</span>
                <input id="exp-amount" type="text" inputmode="decimal" placeholder="0,00" required />
              </label>
              <label class="field">
                <span class="field-label">Categoria</span>
                <select id="exp-category" required></select>
              </label>
              <label class="field">
                <span class="field-label">Data</span>
                <input id="exp-date" type="date" required />
              </label>
            </div>
            <div class="form-actions">
              <p id="expense-message" class="form-message"></p>
              <button type="submit" class="btn btn-primary">Salvar gasto</button>
            </div>
          </form>
        </div>

        <div class="panel">
          <div class="panel-head">
            <h3 class="panel-title">Histórico</h3>
            <div class="filter-row">
              <select id="filter-month" class="mini-select"></select>
              <select id="filter-category" class="mini-select">
                <option value="">Todas as categorias</option>
              </select>
            </div>
          </div>
          <div id="no-data" class="empty hidden">Nenhum gasto por aqui ainda. Adicione o primeiro acima! 🎉</div>
          <div class="group-list" id="expense-groups"></div>
        </div>
      </section>

      <!-- Administração -->
      <section id="view-admin" class="view hidden">
        <div class="page-head">
          <h2 class="page-title">Administração</h2>
          <p class="page-sub">Visão geral do sistema para o administrador.</p>
        </div>

        <div class="admin-stats">
          <div class="stat-card">
            <p class="stat-label">Total gasto (todos)</p>
            <p class="stat-value" id="admin-total">R$ 0,00</p>
          </div>
          <div class="stat-card">
            <p class="stat-label">Usuários ativos</p>
            <p class="stat-value" id="admin-users">0</p>
          </div>
          <div class="stat-card">
            <p class="stat-label">Gasto médio / usuário</p>
            <p class="stat-value" id="admin-avg">R$ 0,00</p>
          </div>
        </div>

        <div class="admin-grid">
          <div class="panel">
            <div class="panel-head"><h3 class="panel-title">Categorias</h3></div>
            <form id="category-form" class="category-form">
              <input id="cat-name" type="text" placeholder="Nova categoria (ex.: Viagem)" required />
              <input id="cat-color" type="color" value="#64748B" title="Cor" />
              <button type="submit" class="btn btn-primary">Adicionar</button>
            </form>
            <div id="category-message" class="form-message"></div>
            <ul id="category-list" class="category-list"></ul>
          </div>

          <div class="panel">
            <div class="panel-head"><h3 class="panel-title">Usuários</h3></div>
            <table class="user-table">
              <thead>
                <tr><th>Usuário</th><th>Gasto total</th><th>Status</th><th></th></tr>
              </thead>
              <tbody id="user-rows"></tbody>
            </table>
          </div>
        </div>
      </section>
    </main>

    <footer class="footer">Feito para quem quer saber exatamente para onde o dinheiro foi.</footer>
  </div>

  <div id="toast" class="toast hidden"></div>

  <script src="/app.js"></script>
</body>
</html>

=== public/styles.css ===
:root{
  --bg:#F3EFE8;
  --surface:#FFFFFF;
  --surface-2:#FBF9F5;
  --ink:#171A1F;
  --ink-soft:#5A6069;
  --line:#E7E0D6;
  --line-strong:#D8CFC2;
  --green:#2F6F4F;
  --green-strong:#245a40;
  --green-soft:#E4EFE9;
  --amber:#B26A05;
  --red:#B23B3B;
  --red-soft:#F6E6E6;
  --shadow:0 1px 2px rgba(23,26,31,.04), 0 12px 30px rgba(23,26,31,.07);
  --radius:16px;
}
*{box-sizing:border-box}
html,body{margin:0;padding:0}
body{
  font-family:"Manrope",system-ui,sans-serif;
  background:var(--bg);
  color:var(--ink);
  line-height:1.5;
  -webkit-font-smoothing:antialiased;
}
.hidden{display:none !important}

/* ---------- AUTENTICAÇÃO ---------- */
.auth-screen{
  min-height:100vh;
  display:flex;
  flex-direction:column;
  align-items:center;
  justify-content:center;
  padding:32px 16px;
  background:
    radial-gradient(900px 500px at 15% -10%, rgba(47,111,79,.10), transparent 60%),
    radial-gradient(700px 500px at 100% 110%, rgba(178,106,5,.10), transparent 55%),
    var(--bg);
}
.auth-card{
  width:100%;
  max-width:420px;
  background:var(--surface);
  border:1px solid var(--line);
  border-radius:22px;
  box-shadow:var(--shadow);
  padding:28px;
  animation:rise .5s ease both;
}
@keyframes rise{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}
.auth-brand{display:flex;align-items:center;gap:12px;margin-bottom:22px}
.brand-dot{
  width:34px;height:34px;border-radius:10px;flex:0 0 auto;
  background:linear-gradient(135deg,var(--green),#5aa87d);
  box-shadow:inset 0 -6px 12px rgba(0,0,0,.15);
}
.brand-title{font-family:"Fraunces",serif;font-size:1.7rem;font-weight:700;margin:0;letter-spacing:-.02em}
.brand-title-sm{font-family:"Fraunces",serif;font-weight:700;font-size:1.15rem;letter-spacing:-.02em}
.brand-sub{margin:2px 0 0;font-size:.85rem;color:var(--ink-soft)}
.auth-tabs{
  display:grid;grid-template-columns:1fr 1fr;gap:6px;
  background:var(--surface-2);border:1px solid var(--line);
  border-radius:12px;padding:4px;margin-bottom:18px;
}
.auth-tab{
  border:0;background:transparent;padding:10px;border-radius:9px;
  font:inherit;font-weight:600;color:var(--ink-soft);cursor:pointer;transition:.2s;
}
.auth-tab.active{background:var(--surface);color:var(--ink);box-shadow:var(--shadow)}
.auth-form{display:flex;flex-direction:column;gap:14px}
.auth-message{margin:0;font-size:.85rem;color:var(--red);min-height:1em}
.auth-footnote{margin-top:20px;font-size:.8rem;color:var(--ink-soft);text-align:center;max-width:320px}

/* ---------- CAMPOS E BOTÕES ---------- */
.field{display:flex;flex-direction:column;gap:6px}
.field-label{font-size:.78rem;font-weight:700;color:var(--ink-soft);text-transform:uppercase;letter-spacing:.05em}
input,select{
  font:inherit;padding:11px 13px;border:1px solid var(--line-strong);
  border-radius:11px;background:var(--surface-2);color:var(--ink);width:100%;
  transition:border-color .15s, box-shadow .15s, background .15s;
}
input:focus,select:focus{
  outline:none;border-color:var(--green);background:var(--surface);
  box-shadow:0 0 0 3px rgba(47,111,79,.15);
}
input[type=color]{padding:4px;height:44px;width:70px;cursor:pointer;background:var(--surface-2)}
.btn{
  font:inherit;font-weight:700;border:1px solid transparent;border-radius:11px;
  padding:12px 18px;cursor:pointer;transition:.18s;
}
.btn:active{transform:translateY(1px)}
.btn-primary{background:var(--green);color:#fff}
.btn-primary:hover{background:var(--green-strong)}
.btn-ghost{background:transparent;border-color:var(--line-strong);color:var(--ink)}
.btn-ghost:hover{background:var(--surface-2)}
.btn-block{width:100%}

/* ---------- TOPO E ABAS ---------- */
.app{min-height:100vh;display:flex;flex-direction:column}
.topbar{
  display:flex;align-items:center;justify-content:space-between;
  padding:14px 22px;background:var(--surface);
  border-bottom:1px solid var(--line);
  position:sticky;top:0;z-index:10;
}
.topbar-left{display:flex;align-items:center;gap:10px}
.topbar-left .brand-dot{width:26px;height:26px;border-radius:8px}
.topbar-right{display:flex;align-items:center;gap:10px}
.user-chip{
  font-weight:700;font-size:.9rem;background:var(--surface-2);
  border:1px solid var(--line);padding:6px 12px;border-radius:999px;
}
.admin-badge{
  font-size:.72rem;font-weight:800;letter-spacing:.04em;text-transform:uppercase;
  background:var(--green-soft);color:var(--green-strong);
  padding:4px 10px;border-radius:999px;
}
.btn-ghost{padding:9px 14px;font-size:.85rem}
.tabs{
  display:flex;gap:6px;padding:14px 22px 0;background:var(--bg);
}
.nav-tab{
  border:0;background:transparent;font:inherit;font-weight:700;font-size:.95rem;
  color:var(--ink-soft);padding:10px 16px;border-radius:12px;cursor:pointer;
  border-bottom:2px solid transparent;transition:.15s;
}
.nav-tab:hover{color:var(--ink)}
.nav-tab.active{color:var(--ink);border-bottom-color:var(--green);background:var(--surface)}
.content{flex:1;padding:22px;max-width:1100px;width:100%;margin:0 auto}
.footer{text-align:center;padding:18px;color:var(--ink-soft);font-size:.8rem}

/* ---------- PÁGINA / CARRINHOS ---------- */
.page-head{
  display:flex;align-items:flex-end;justify-content:space-between;
  gap:16px;margin:4px 0 18px;flex-wrap:wrap;
}
.page-title{font-family:"Fraunces",serif;font-size:1.9rem;margin:0;letter-spacing:-.02em}
.page-sub{margin:2px 0 0;color:var(--ink-soft);font-size:.9rem}
.view{display:flex;flex-direction:column;gap:18px;animation:fade .35s ease both}
@keyframes fade{from{opacity:0}to{opacity:1}}

.stats-grid{
  display:grid;grid-template-columns:1.4fr 1fr 1fr;gap:14px;
}
.stat-card{
  background:var(--surface);border:1px solid var(--line);
  border-radius:var(--radius);padding:18px;box-shadow:var(--shadow);
  transition:transform .18s, box-shadow .18s;
}
.stat-card:hover{transform:translateY(-2px);box-shadow:0 3px 8px rgba(23,26,31,.06), 0 18px 40px rgba(23,26,31,.09)}
.stat-hero{background:linear-gradient(150deg,#1f3d2d,#2f6f4f);border-color:transparent;color:#fff}
.stat-hero .stat-label{color:rgba(255,255,255,.75)}
.stat-hero .stat-hint{color:rgba(255,255,255,.7)}
.stat-label{margin:0;font-size:.78rem;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:var(--ink-soft)}
.stat-value{font-family:"Fraunces",serif;font-size:2.1rem;font-weight:700;margin:6px 0 2px;letter-spacing:-.02em}
.stat-value-sm{font-size:1.5rem}
.stat-hint{margin:0;font-size:.8rem;color:var(--ink-soft)}

.panel{
  background:var(--surface);border:1px solid var(--line);
  border-radius:var(--radius);padding:20px;box-shadow:var(--shadow);
}
.panel-head{
  display:flex;align-items:center;justify-content:space-between;gap:12px;
  flex-wrap:wrap;margin-bottom:16px;
}
.panel-title{font-family:"Fraunces",serif;font-size:1.25rem;margin:0}
.form-grid{display:grid;grid-template-columns:1.6fr .9fr 1fr .9fr;gap:12px}
.form-actions{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:14px;flex-wrap:wrap}
.form-message{margin:0;font-size:.85rem;color:var(--red);min-height:1em}

.mini-select{width:auto;min-width:150px;padding:9px 11px;font-size:.88rem}
.filter-row{display:flex;gap:10px;flex-wrap:wrap}

/* ---------- LISTA DE GASTOS ---------- */
.empty{text-align:center;color:var(--ink-soft);padding:34px 10px;font-size:.95rem}
.group-list{display:flex;flex-direction:column;gap:16px}
.expense-group{border-top:1px solid var(--line);padding-top:14px}
.expense-group:first-child{border-top:0;padding-top:0}
.group-head{display:flex;align-items:baseline;justify-content:space-between;margin-bottom:8px}
.group-date{font-weight:800;font-size:.92rem}
.group-date-sub{color:var(--ink-soft);font-weight:600;font-size:.78rem;margin-left:8px}
.group-total{font-weight:700;font-size:.92rem}
.expense-item{
  display:flex;align-items:center;gap:12px;padding:9px 10px;border-radius:12px;
  transition:background .15s;
}
.expense-item:hover{background:var(--surface-2)}
.cat-chip{
  display:inline-flex;align-items:center;gap:7px;flex:1;min-width:0;
  font-size:.9rem;font-weight:600;
}
.cat-dot{width:11px;height:11px;border-radius:50%;flex:0 0 auto}
.exp-desc{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.exp-cat-name{color:var(--ink-soft);font-size:.82rem;font-weight:700;margin-left:2px}
.exp-amount{font-weight:800;font-variant-numeric:tabular-nums;white-space:nowrap}
.exp-del{
  border:0;background:transparent;color:var(--line-strong);cursor:pointer;
  font-size:1.05rem;padding:4px 8px;border-radius:8px;line-height:1;
  opacity:.4;transition:.15s;
}
.expense-item:hover .exp-del{opacity:1}
.exp-del:hover{color:var(--red);background:var(--red-soft)}

/* ---------- ADMIN ---------- */
.admin-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
.admin-grid{display:grid;grid-template-columns:1fr 1.3fr;gap:18px;align-items:start}
.category-form{display:grid;grid-template-columns:1fr auto auto;gap:10px;margin-bottom:10px}
.category-list{list-style:none;margin:8px 0 0;padding:0;display:flex;flex-direction:column;gap:6px}
.category-row{
  display:flex;align-items:center;gap:12px;padding:10px 12px;
  border:1px solid var(--line);border-radius:12px;background:var(--surface-2);
}
.category-row .cat-dot{width:14px;height:14px}
.category-row .cat-name{flex:1;font-weight:700}
.category-row.is-off .cat-name{color:var(--ink-soft);text-decoration:line-through}
.category-row .count{font-size:.78rem;color:var(--ink-soft);font-weight:700}
.toggle{
  border:1px solid var(--line-strong);background:var(--surface);cursor:pointer;
  font:inherit;font-size:.78rem;font-weight:700;padding:6px 12px;border-radius:999px;transition:.15s;
}
.toggle:hover{border-color:var(--green);color:var(--green-strong)}
.toggle.off{border-color:var(--red-soft);background:var(--red-soft);color:var(--red)}
.toggle:disabled{opacity:.4;cursor:not-allowed}

.user-table{width:100%;border-collapse:collapse;font-size:.9rem}
.user-table th{
  text-align:left;font-size:.72rem;text-transform:uppercase;letter-spacing:.05em;
  color:var(--ink-soft);padding:8px 10px;border-bottom:1px solid var(--line);
}
.user-table td{padding:11px 10px;border-bottom:1px solid var(--line);vertical-align:middle}
.user-table tr:last-child td{border-bottom:0}
.user-name{font-weight:700}
.user-total{font-variant-numeric:tabular-nums;font-weight:700}
.status-pill{font-size:.72rem;font-weight:800;padding:3px 10px;border-radius:999px}
.status-on{background:var(--green-soft);color:var(--green-strong)}
